// Exercise the installed annotation CLI and HTTP service without a test runner.
import {mkdtemp,mkdir,writeFile,rm} from 'node:fs/promises';
import {join,resolve} from 'node:path';
const sourceRoot=process.cwd();
const directory=await mkdtemp('/tmp/pins-integration-smoke-');
const repository=join(directory,'repository');
const cli=join(sourceRoot,'mise/conf.d/devtools-agent/bundles/developer/skills/browsers/collect-feedback/scripts/collect-feedback.ts');
const collector=join(sourceRoot,'mise/conf.d/devtools-agent/bundles/developer/skills/browsers/collect-evidence/scripts/collect-evidence.ts');
const page=Bun.serve({hostname:'127.0.0.1',port:0,fetch:()=>new Response('<!doctype html><h1>Annotation integration smoke</h1>',{headers:{'Content-Type':'text/html'}})});
let server;
try {
  await mkdir(repository);
  await command('git',['init','--quiet',repository]);
  await command('git',['-C',repository,'remote','add','origin','https://example.invalid/pins/smoke.git']);
  await writeFile(join(repository,'.context-routes.toml'),'schema = 2\n[records.alignment]\nadapter = "markdown"\nstore = "repository"\n[records.tickets]\nadapter = "local-markdown"\nstore = "repository"\n[records.initiatives]\nadapter = "markdown"\nstore = "repository"\n[records.sources]\nadapter = "files"\nstore = "inherit:alignment"\n[records.workflows]\nadapter = "files"\nstore = "repository"\n[records.evidence]\nadapter = "files"\nstore = "repository"\n');
  const working=join(directory,'working');
  const run=await invoke(collector,['init',working,'--repository',repository,'--workflow','pins-smoke','--run','source','--driver','playwright']);
  await writeFile(join(working,'plan.ts'),'export const plan = '+JSON.stringify({schema:'collect-evidence/v1',kind:'plan',workId:'pins-smoke',driver:'playwright',base:page.url.origin,approval:{origins:[page.url.origin],confirmations:[]},tests:[{id:'original',claim:'Preserve original pixels',pass:'Heading exists',fail:'Heading missing',steps:[{do:'navigate',says:'Open owned page',to:'/',shot:''},{do:'expect',says:'Inspect heading',locator:'h1',text:'Annotation integration smoke',shot:'original'}]}]})+';');
  for (const step of ['render','compile','run']) await invoke(collector,[step,working]);
  const imported=await invoke(cli,['init',run.destination.path,'--repository',repository,'--workflow','pins-smoke','--session','review']);
  const session=imported.destination.path;
  const reserve=Bun.serve({hostname:'127.0.0.1',port:0,fetch:()=>new Response()}); const port=reserve.port; await reserve.stop(true);
  server=await start(session,port);
  const origin=`http://127.0.0.1:${port}`;
  const state=await (await fetch(origin+'/api/v1/session')).json();
  const cases=await (await fetch(origin+'/api/v1/cases')).json();
  const asset=cases.cases[0].assets[0];
  const input={schema:'collect-feedback/v1',kind:'annotation',id:crypto.randomUUID(),sessionId:'review',caseId:'original',assetId:asset.id,sourceSha256:asset.sha256,originalWidth:asset.width,originalHeight:asset.height,geometry:{x:0.5,y:0.5,width:0,height:0},priority:'P2',comment:'Integration smoke durable note'};
  const saved=await fetch(origin+'/api/v1/annotations',{method:'POST',headers:{Origin:origin,'X-Write-Token':state.writeToken,'Content-Type':'application/json'},body:JSON.stringify(input)});
  if(saved.status!==201)throw Error('Annotation save failed: '+saved.status+' '+await saved.text());
  const record=await saved.json();
  server.kill('SIGTERM'); if(await server.exited!==0)throw Error('Server shutdown failed'); server=undefined;
  const exported=await invoke(cli,['export',session]);
  const note=exported.annotations.find(note=>note.id===input.id);
  if(!note||note.comment!==input.comment||note.sourceSha256!==asset.sha256)throw Error('Durable export did not preserve note identity');
  console.log(JSON.stringify({scenario:'installed annotation save then offline export',saved_id:note.id,comment:note.comment,sourceSha256:note.sourceSha256,server_exit:0}));
} finally {
  if(server){server.kill('SIGTERM');await server.exited;}
  await page.stop(true);
  await command('chmod',['-R','u+rwX',directory]);
  await rm(directory,{recursive:true,force:true});
}
async function command(executable,args){const p=Bun.spawn([executable,...args],{cwd:directory,stdout:'pipe',stderr:'pipe'});const [out,err]=await Promise.all([new Response(p.stdout).text(),new Response(p.stderr).text()]);if(await p.exited!==0)throw Error(executable+' failed: '+out+err);return out;}
async function invoke(executable,args){return JSON.parse(await command(executable,[...args,'--json','--no-color','--no-input']));}
async function start(session,port){const p=Bun.spawn([cli,'serve',session,'--port',String(port),'--json'],{cwd:directory,stdout:'pipe',stderr:'pipe'});const reader=p.stdout.getReader();let text='';while(!text.includes('\n')){const next=await reader.read();if(next.done)throw Error('Service exited before readiness');text+=new TextDecoder().decode(next.value);}reader.releaseLock();if(!JSON.parse(text.trim()).success)throw Error('Service not ready');return p;}
